  it('expires entries after ttlMs', async () => {
    const m = new MemoryStore<string>();
    m.set('k', 'v', 5);
    await new Promise(r => setTimeout(r, 15));
    assert.equal(m.get('k'), undefined);
  });
  it('size() counts expired-but-unaccessed entries (likely a bug)', () => {
    const m = new MemoryStore<string>();
    m.set('k', 'v', 1);
    // k has expired but never been get()'d, so get() would purge it
    // but size() reads Map.size without touching expiry:
    assert.equal(
