    const buf = readFileSync(logPath);
    writeFileSync(logPath, Buffer.concat([buf, Buffer.from([0x00, 0x01, 0x02])]));

    const log2 = new RvfEventLog({ logPath });
    await log2.initialize();
    const events = await log2.getEvents('a');
    assert.equal(events.length, 1, 'the clean event before the truncation must survive');
